function normalizePerson(value={}){return {id:String(value.id||crypto.randomUUID()),name:String(value.name||'').trim().slice(0,80),phone:String(value.phone||'').trim().slice(0,16),category:String(value.category||'Prospects').trim().slice(0,80),company:String(value.company||'').trim().slice(0,100),role:String(value.role||'').trim().slice(0,100),notes:String(value.notes||'').trim().slice(0,1000),callConsent:value.callConsent===true,recordingConsent:value.recordingConsent===true}}
