function overview(){const total=state.calls.reduce((sum,c)=>sum+c.duration,0),completed=state.calls.filter(c=>c.status==='Completed').length;return head('Closer to your customers.','Romanian numbers. A Romanian-speaking agent. Your next conversation.',btn('Make a call','call',true,'plus'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('spark')} BUILT FOR BUSINESS IN ROMANIA</div><h2>Local numbers.<br>Conversations that connect.</h2><p>From București to Cluj, let your AI agent handle<br>the follow-up. In your customers’ own language.</p><div class="actions">${btn('Get a phone number','numbers',true,'plus')}<button class="btn" id="try-romania">Try Romania demo ↗</button></div></div><div class="hero-visual"><div class="orbit o3"></div><div class="orbit"></div><div class="orbit o2"></div>${orb()}<div class="floating one"><span class="circle-icon">${icon('phone')}</span><span><strong>A more human connection</strong><small>Powered by GPT-Live-1</small></span></div><div class="floating two"><span class="circle-icon">${icon('check')}</span><span><strong>Every conversation counts</strong><small>Your company, always present</small></span></div></div></section><section class="metrics">${[['Total calls',state.calls.length,'Your preview activity','phone'],['Conversation time',`${Math.floor(total/60)}<span style="font-size:13px;letter-spacing:0"> min</span>`,'Across simulated calls','clock'],['Completion rate',state.calls.length?Math.round(completed/state.calls.length*100)+'%':'—','Completed preview calls','check'],['Phone numbers',state.numbers.length,'<span class="green">Preview numbers</span> · No charges','phone']].map(([title,value,bottom,i])=>`<div class="metric"><div class="metric-top">${title}${icon(i)}</div><div class="metric-value">${value}</div><div class="metric-bottom">${bottom}</div></div>`).join('')}</section><div class="grid-two"><section class="card"><div class="card-head"><div><h3>Let’s get you calling</h3><p>Three small steps. One big hello.</p></div><span class="tag">${Number(!!state.numbers.length)+Number(state.saved)+Number(!!state.calls.length)} of 3 complete</span></div>${[['phone','Get your business number','Choose a local number that feels close to home.','numbers',state.numbers.length],['agent','Make your agent yours','Give it a name, a voice, and a little direction.','agent',state.saved],['phone','Try your first conversation','See the calling flow with a simulated test call.','call',state.calls.length]].map(([i,title,desc,go,done])=>`<div class="setup-step"><div class="step-icon">${icon(done?'check':i)}</div><div class="step-copy"><strong>${title}</strong><p>${desc}</p></div><button class="step-go" data-go="${go}" aria-label="${title}">${done?'✓':'↗'}</button></div>`).join('')}</section><section class="card"><div class="card-head"><h3>Default agent for new numbers</h3><button class="btn ghost" data-go="agent">Edit agent ↗</button></div><div class="agent-preview"><div class="agent-top"><div class="agent-face">✧</div><div><strong>${esc(state.agent.name)}</strong><small>${esc(state.agent.role)} agent</small></div><span class="tag ${state.saved?'green':''}">${state.saved?'Configured':'Draft'}</span></div><div class="agent-props"><div><small>MODEL</small>GPT-Live-1</div><div><small>LANGUAGE</small>${esc(state.agent.language)}</div><div><small>VOICE</small>${esc(state.agent.voice[0].toUpperCase()+state.agent.voice.slice(1))}</div></div>${btn('Configure your agent','agent',false,'agent').replace('class="btn ','class="btn full ')}</div></section></div><section class="card recent"><div class="card-head"><div><h3>Recent conversations</h3><p>${state.calls.length?'Your latest simulated calls':'A little preview of what’s to come'}</p></div><button class="btn ghost" data-go="history">View all calls ↗</button></div>${table(state.calls.length?state.calls.slice(0,3):samples)}</section>`}
function table(calls){return `<div class="table-wrap"><table><thead><tr><th>CONTACT</th><th>AGENT</th><th>STATUS</th><th>DURATION</th><th>WHEN</th><th></th></tr></thead><tbody>${calls.map(c=>`<tr><td><div class="call-person"><span class="mini-avatar">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div>${esc(c.name)}<small>${esc(c.to)}</small></div></div></td><td>${esc(c.agent||state.agent.name)}<small>${c.sample?'Sample conversation':'Simulated call'}</small></td><td><span class="tag ${c.status==='Completed'?'green':c.status==='No answer'?'orange':''}">${c.status==='Completed'?'✓ ':''}${esc(c.status)}</span></td><td class="muted">${c.duration?`${Math.floor(c.duration/60)}m ${c.duration%60}s`:'—'}</td><td class="muted">${esc(c.time)}</td><td><button class="table-button" data-detail="${esc(c.id)}" aria-label="View call with ${esc(c.name)}">↗</button></td></tr>`).join('')}</tbody></table></div>`}
