async function showRecording(call){showModal(modalHead('Conversation recording')+'<p class="modal-desc">Checking recording availability…</p>');try{const data=await provider('recordings&call='+call);const recording=data.recordings.find(r=>r.status==='completed');if(!recording){showModal(modalHead('Conversation recording')+`<p class="modal-desc">${data.recordings.length?'The recording is still processing.':'No recording is available yet. Unanswered calls have no conversation to record.'}</p><button class="btn" id="retry-recording">Check again</button>`);document.querySelector('#retry-recording').onclick=()=>showRecording(call);return}showModal(modalHead('Conversation recording')+'<p class="modal-desc">Loading your private recording…</p>');const r=await fetch('/api/telephony?action=audio&recording='+recording.sid,{headers:{Authorization:'Bearer '+ownerToken}});if(!r.ok)throw new Error('Unable to load recording. Please try again.');if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(await r.blob());showModal(modalHead('Conversation recording')+`<p class="modal-desc">${esc(recording.duration)} seconds · ${esc(recording.channels)} channels<br>Stored by Twilio. Available only through this authenticated workspace.</p><audio controls preload="metadata" src="${audioURL}" style="width:100%"></audio><div class="modal-actions"><a class="btn" href="${audioURL}" download="masscall-${recording.sid}.mp3">Download MP3</a><button class="btn primary" data-close>Done</button></div>`)}catch(e){showModal(modalHead('Recording unavailable')+`<p class="modal-desc">${esc(e.message)}</p>`)}}
document.addEventListener('click',async e=>{if(e.target.closest('#open-live'))openLive();const usePerson=e.target.closest('[data-person-use]');if(usePerson){fillPersonIntoCall(state.people.find(item=>item.id===usePerson.dataset.personUse));return}const editPerson=e.target.closest('[data-person-edit]');if(editPerson){editDirectoryPerson(state.people.find(item=>item.id===editPerson.dataset.personEdit));return}const deletePerson=e.target.closest('[data-person-delete]');if(deletePerson){const person=state.people.find(item=>item.id===deletePerson.dataset.personDelete);if(person&&confirm('Delete '+person.name+' from this workspace?')){state.people=state.people.filter(item=>item.id!==person.id);const form=document.querySelector('#real-call');if(form.elements.personId.value===person.id){form.elements.personId.value='';form.elements.personCategory.value='';form.elements.personCompany.value='';form.elements.personRole.value='';form.elements.personNotes.value=''}save();await liveConsole()}return}const useTemplate=e.target.closest('[data-template-use]');if(useTemplate){const template=state.callTemplates.find(item=>item.id===useTemplate.dataset.templateUse);if(template){document.querySelector('#real-template').value=template.id;fillTemplateFields(template);showLivePanel('call')}return}const editTemplate=e.target.closest('[data-template-edit]');if(editTemplate){editCallTemplate(state.callTemplates.find(item=>item.id===editTemplate.dataset.templateEdit));return}const deleteTemplate=e.target.closest('[data-template-delete]');if(deleteTemplate){const template=state.callTemplates.find(item=>item.id===deleteTemplate.dataset.templateDelete);if(template&&confirm('Delete the '+template.name+' template?')){state.callTemplates=state.callTemplates.filter(item=>item.id!==template.id);const form=document.querySelector('#real-call');if(form.elements.templateId.value===template.id)form.elements.templateId.value='';save();await liveConsole()}return}if(e.target.closest('#live-agent-back')){showLivePanel('call');return}const recording=e.target.closest('[data-recording]');if(recording)showRecording(recording.dataset.recording);const hang=e.target.closest('[data-hangup]');if(hang){hang.disabled=true;try{await provider('hangup',{call:hang.dataset.hangup});await liveConsole()}catch(error){toast(error.message);hang.disabled=false}}const buy=e.target.closest('[data-real-buy]');if(buy){const number=buy.dataset.realBuy;showModal(modalHead('Purchase a phone number')+`<p class="modal-desc">You are purchasing <b>${esc(number)}</b> from Twilio. Monthly rental and usage charges will be billed to your connected Twilio account.</p><p class="hint">Review the number’s current price and any registration requirements in Twilio before purchasing. This first version does not add a Masscall markup.</p><div class="actions" style="margin-top:20px"><a class="btn" href="https://console.twilio.com/us1/develop/phone-numbers/manage/search" target="_blank" rel="noreferrer">Review in Twilio ↗</a></div><label class="check-label"><input id="purchase-consent" type="checkbox">I have reviewed the current recurring price and authorize this purchase.</label><p id="purchase-error" class="inline-note" role="alert"></p><div class="modal-actions"><button class="btn" data-close>Cancel</button><button id="purchase-real" class="btn primary" disabled>Purchase number</button></div>`);document.querySelector('#purchase-consent').onchange=e=>document.querySelector('#purchase-real').disabled=!e.target.checked;document.querySelector('#purchase-real').onclick=async e=>{e.target.disabled=true;try{await provider('purchase',{number,confirmPurchase:true});preferredLiveNumber=number;state.identities[numberKey(number)]=normalizeIdentity({...state.agent,label:number});save();identityTarget=numberKey(number);navigate('agent');toast('Number purchased. Configure its agent, then return to place your test call.')}catch(error){document.querySelector('#purchase-error').textContent=error.message;e.target.disabled=false}}}});
